    top->Parent = p;
    if (x->Right)
        top->Right = CopyTree(x->Right, top);
    p = top;
    x = x->Left;
    while (x != 0) {
        TNode<V>* y = CloneNode(x);
        p->Left = y;
        y->Parent = p;
        if (x->Right)
